uint8_t dsky_decimal_select_checkpoint_input(uint8_t n,apollo_overlay_state *s,p66_bias_io *io,enum dsky_nv_mission *mission){if(n>=128u)return 0;dsky_decimal_select_input(s,io,dsky_decimal_select_numbers[n],mission);return 1;}
uint16_t dsky_decimal_select_checkpoint(uint8_t n,apollo_overlay_state *s,apollo_overlay_state *before){p66_bias_io io,old;enum dsky_nv_mission mission;uint16_t f,p,end,failures=0;agc_word route=077777,expected_route;if(!dsky_decimal_select_checkpoint_input(n,s,&io,&mission))return 1;*before=*s;old=io;if(dsky_decimal_select(s,&io,mission,&route)!=P66_BIAS_OK)++failures;expected_route=(agc_word)(((unsigned)before->words[before->words[0140]==1u?0147u:0153u]>>(before->words[0140]==1u?5u:5u*before->words[0117]))&037u);if(route!=expected_route)++failures;p=dsky_decimal_select_after_offsets[n];end=dsky_decimal_select_after_offsets[n+1u];for(f=0;f<2050u;++f){uint16_t expected=f<2048u?before->words[f]:f==2048u?old.superbank:old.interrupt_enabled;uint16_t actual=f<2048u?s->words[f]:f==2048u?io.superbank:io.interrupt_enabled;if(p<end&&dsky_decimal_select_after_patch[p][0]==f)expected=dsky_decimal_select_after_patch[p++][1];if(actual!=expected)++failures;}if(p!=end)++failures;return failures;}
